  git(repoRoot, ['merge', '--no-ff', '-q', '-m', 'earlier successful merge', 'fgw/demo-item']);

  // Something else broke on HEAD since that earlier merge landed.
  fs.unlinkSync(path.join(repoRoot, 'produced.txt'));
  git(repoRoot, ['add', '-A']);
